{
  "diagnosis": "The option_selection module fails to prioritize the most specific indication-matched therapy when multiple options are plausible; it should rank options by how directly each treats the stated condition, using patient-specific safety only to exclude contraindicated options, not to override a clearly indicated first-line choice.",
  "skills": [
    {
      "id": "indication_specificity_ranking",
      "text": "When several options are not contraindicated, select the one whose approved or standard indication most specifically matches the patient's stated diagnosis; do not choose a broader or less specific alternative merely because it is also safe."
    },
    {
      "id": "safety_as_filter_not_override",
      "text": "Use patient-specific safety facts to exclude unsafe options, but once an option is safe, prefer the option with the strongest indication match rather than the one with the most cautious safety profile."
    }
  ],
  "focus_terms": [
    "most specific indication",
    "first-line for stated diagnosis",
    "safety filter",
    "indication match"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. Rank options by how specifically their approved or standard use matches the stated diagnosis; use safety facts only to exclude contraindicated options, not to prefer a less specific but safer alternative over a clearly indicated first-line choice."
  }
}

{
  "diagnosis": "The option_selection module fails to prioritize the option that best matches the patient's specific clinical context and prior treatment response, instead selecting options that are either less effective, already failed, or not indicated.",
  "skills": [
    {
      "id": "prior_treatment_response",
      "text": "When the patient reports inadequate response or failure of a current medication for the same indication, avoid selecting that same medication again; prefer an alternative with a different mechanism or better efficacy for the condition."
    },
    {
      "id": "indication_match",
      "text": "Select the option whose primary indication directly matches the patient's diagnosed or suspected condition; do not choose options that are indicated for unrelated conditions or are not first-line for the target condition."
    },
    {
      "id": "safety_and_adherence",
      "text": "When the patient has difficulty adhering to a medication regimen or has a contraindication, avoid options that require strict adherence or are contraindicated; prefer options with simpler dosing or better safety profile for that patient."
    }
  ],
  "focus_terms": [
    "inadequate response",
    "contraindication",
    "adherence",
    "indication",
    "first-line"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. Prioritize options that directly treat the diagnosed condition, avoid reusing a medication that has already failed or is not working, and avoid options that are contraindicated or impractical due to adherence issues. When multiple options are indicated, prefer the one with the strongest evidence or best fit for the patient's specific context."
  }
}

{
