    {
      "id": "avoid_symptomatic_only",
      "text": "Do not choose an option solely because it addresses a symptom or a secondary problem; the primary indication must match the diagnosed condition."
    }
  ],
  "focus_terms": [
    "indication",
    "first-line",
    "specific treatment",
    "diagnosis match"
  ],
