{
  "diagnosis": "The option_selection module fails to prioritize the most specific indication-matched therapy when multiple options are plausible; it needs a generalized procedure to rank options by exact indication fit and patient-specific safety.",
  "skills": [
    {
      "id": "indication_specificity_ranking",
      "text": "When multiple options are clinically plausible, select the one whose approved indication most precisely matches the diagnosed condition and the patient's documented context; prefer a targeted first-line therapy over a broader or less specific alternative, and reject options whose primary indication is unrelated to the diagnosis."
    },
    {
      "id": "safety_filter_before_ranking",
      "text": "Before ranking options by indication, exclude any option that is contraindicated or unsafe given the patient's stated conditions, current medicines, or documented allergies; if no safe option remains, choose the safest available option rather than an unsafe one."
    }
  ],
  "focus_terms": [
    "indication match",
    "first-line therapy",
    "contraindication",
    "patient-specific safety"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. Rank candidate options by how specifically their approved indication matches the diagnosed condition and the patient's documented context; prefer targeted first-line therapy over broader or less specific alternatives. Exclude options whose primary indication is unrelated to the diagnosis. Apply safety exclusions before final ranking, and if no fully safe option exists, choose the safest available option rather than an unsafe one."
  }
}

{
  "diagnosis": "Option selection sometimes fails to prioritize the option whose indication most directly matches the stated condition when multiple options are plausible; the selection rule should require a direct indication match before considering secondary safety preferences.",
  "skills": [
    {
      "id": "indication_first_selection",
      "text": "When choosing among plausible options, first identify the option whose labeled indication most directly matches the stated diagnosis or syndrome; do not let a secondary safety preference override a clear indication match unless the safety issue is explicitly present in the patient facts."
    },
    {
      "id": "avoid_unsupported_safety_override",
      "text": "Do not downgrade an otherwise indicated option based on a hypothetical or absent contraindication; only apply a safety-based override when the patient evidence explicitly states the relevant contraindication, interaction, or organ dysfunction."
    }
  ],
  "focus_terms": [
    "direct indication match",
    "explicit contraindication",
    "stated diagnosis"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. First require a direct match between the option's labeled indication and the stated condition. Then apply safety only when the patient facts explicitly document a relevant contraindication, interaction, or organ dysfunction. Do not let a secondary safety preference override a clear indication match unless that safety issue is explicitly present."
  }
}

{
  "diagnosis": "The option_selection module overweights a single stated patient fact (e.g., a medication already being taken, a family history, or a symptom) and fails to compare all options against the full indication and safety profile, leading to choices that are not the best fit.",
  "skills": [
    {
      "id": "compare_all_options",
      "text": "For every option, explicitly state whether it is indicated for the diagnosed condition and whether it is safe given the patient's facts. Eliminate options that are not indicated or are unsafe, then choose the remaining option that best matches the diagnosis and patient-specific safety."
    },
    {
      "id": "avoid_single_fact_shortcut",
      "text": "Do not choose an option solely because it relates to one patient fact (such as a current medication, a family history, or a single symptom). Instead, require that the option also directly treats the diagnosed condition and is the most appropriate among the available choices."
    },
    {
      "id": "prefer_first_line_when_safe",
      "text": "When multiple options are indicated and safe, prefer the one that is standard first-line therapy for the diagnosed condition, unless a patient-specific contraindication or interaction makes another option clearly safer."
    }
  ],
  "focus_terms": [
    "indicated for the diagnosed condition",
    "patient-specific safety",
    "first-line therapy",
    "compare all options"
  ],
  "modules": {
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. For each option, verify whether it is indicated for the diagnosed condition and whether it is safe given the patient's stated facts. Eliminate options that are not indicated or are unsafe. Among remaining options, prefer the one that is standard first-line therapy for the condition, unless a patient-specific contraindication or interaction makes another option clearly safer. Do not choose an option solely because it relates to one patient fact; require that it also directly treats the diagnosed condition and is the most appropriate among the choices."
  }
}

{
  "diagnosis": "The option_selection module overweights the clinician's stated diagnostic hypothesis and underweights the patient's full symptom profile and medication history, causing it to choose treatments that are less appropriate than alternatives that better match the complete evidence.",
  "skills": [
    {
      "id": "symptom_profile_match",
      "text": "When selecting among medication options, compare each option against the full set of patient-reported symptoms and the clinician's working diagnosis, not just the diagnosis label. Prefer options whose labeled indications cover the dominant symptom cluster (e.g., pain, swelling, urinary symptoms, GI symptoms) and avoid options that treat unrelated conditions."
    },
    {
      "id": "medication_history_interaction",
      "text": "Before finalizing an option, check the patient's current medication list for potential interactions or contraindications. If an option has a known interaction with a current medication, deprioritize it even if it otherwise matches the indication."
    },
    {
      "id": "avoid_unrelated_treatments",
      "text": "Eliminate options that are indicated for conditions not present in the patient's presentation (e.g., cancer, thrombocytopenia, hormone replacement) unless the dialogue explicitly supports that condition."
    }
  ],
  "focus_terms": [
    "indication match",
    "symptom cluster",
    "current medications",
    "contraindication",
    "interaction"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. Compare each option against the full symptom profile, the clinician's working diagnosis, and the patient's current medications. Prefer options whose labeled indications cover the dominant symptom cluster and avoid options that treat unrelated conditions or have known interactions with current medications."
  }
}

{
