  "skills": [
    {
      "id": "primary_problem_priority",
      "text": "When multiple patient problems are present, identify the most active or dominant condition that requires immediate treatment and select the option with the strongest indication for that primary problem, rather than an option that only addresses a secondary or less urgent issue."
    },
    {
      "id": "avoid_incidental_medication_bias",
      "text": "Do not let a medication mentioned incidentally in the history (e.g., one taken for an unrelated condition) drive the choice unless it directly interacts with or contraindicates the treatment for the primary problem."
    },
    {
      "id": "mechanism_avoidance_after_failure",
      "text": "If the patient is already on a drug from a particular class and symptoms persist or worsen, avoid selecting another drug from the same class unless there is a clear reason to expect a different response; prefer a different mechanism of action."
    }
  ],
  "focus_terms": [
    "primary indication",
    "dominant problem",
    "active condition",
    "treatment priority",
    "mechanism of action",
    "therapeutic class"
  ],
  "modules": {
