{
  "diagnosis": "option_selection failed to prioritize the patient's stated primary condition over incidental medication-related concerns, causing wrong choices when a distractor was tied to the current drug.",
  "skills": [
    {
      "id": "primary_indication_first",
      "text": "When selecting an option, first identify the patient's stated diagnosis or presenting problem and require the option to be indicated for that primary condition; do not let a medication-related side effect or interaction concern override the need to treat the stated condition unless it makes the option unsafe."
    },
    {
      "id": "distractor_medication_bias",
      "text": "If an option is attractive only because it relates to the patient's current medication or a mentioned side effect, but it is not indicated for the stated condition, treat it as a distractor and prefer the option that directly treats the condition."
    },
    {
      "id": "safety_does_not_replace_indication",
      "text": "A safe option that lacks indication for the patient's condition should not be chosen over an indicated option; safety screening filters unsafe options but does not determine the best treatment."
    }
  ],
  "focus_terms": [
    "indicated for the stated condition",
    "primary diagnosis",
    "distractor",
    "side effect",
    "interaction concern"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. First anchor on the patient's stated condition or presenting problem and require the option to be indicated for it. Then apply safety screening to exclude contraindicated or interacting options. Do not let a medication-related side effect, monitoring concern, or interaction worry replace the need for indication; if an option is attractive only because it relates to a current medicine or mentioned side effect but is not indicated for the stated condition, treat it as a distractor. A safe but non-indicated option should not be selected over an indicated option."
  }
}

{
  "diagnosis": "The option_selection module fails to prioritize the option that is both indicated for the diagnosed condition and safest given the patient's current medications and comorbidities; it sometimes selects a less appropriate option despite correct evidence extraction and safety checking.",
  "skills": [
    {
      "id": "indication_safety_priority",
      "text": "When choosing among options, first eliminate any option that is not indicated for the diagnosed condition. Among remaining indicated options, prefer the one with the fewest patient-specific safety concerns (contraindications, interactions, or additive adverse effects). If multiple options are indicated and safe, prefer the one that is most standard or best-supported for the specific diagnosis."
    },
    {
      "id": "avoid_contraindicated_or_interacting",
      "text": "Do not select an option that is contraindicated by a stated patient fact or that has a significant interaction with a current medication when a safer indicated alternative exists."
    },
    {
      "id": "prefer_standard_first_line",
      "text": "When several options are indicated and safe, choose the one that is generally considered first-line or most specific for the diagnosed condition, rather than a less specific or adjunctive agent."
    }
  ],
  "focus_terms": [
    "indicated",
    "contraindicated",
    "interaction",
    "first-line",
    "safest"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. First, eliminate options not indicated for the diagnosed condition. Then, among indicated options, eliminate those with contraindications or significant interactions based on stated patient facts. Among remaining options, prefer the one that is most standard, first-line, or best-supported for the specific diagnosis. If no option is clearly indicated, choose the safest option that is least likely to cause harm given the patient's current medications and comorbidities."
  }
}

